trait WidgetFactory {
    fn button(&self, label: &str) -> Box<dyn Button>;
    fn slider(&self, min: i32, max: i32) -> Box<dyn Slider>;
}

struct DarkTheme;
impl WidgetFactory for DarkTheme {
    fn button(&self, label: &str) -> Box<dyn Button> { Box::new(DarkButton::new(label)) }
    fn slider(&self, min: i32, max: i32) -> Box<dyn Slider> { Box::new(DarkSlider::new(min, max)) }
}

enum Theme { Dark, Light }
enum Widget { Button(Button), Slider(Slider) }

impl Theme {
    fn make(&self, kind: &str) -> Result<Widget, &'static str> {
        match (self, kind) {
            (Theme::Dark, "button") => Ok(Widget::Button(Button::dark())),
            (Theme::Dark, "slider") => Ok(Widget::Slider(Slider::dark())),
            (Theme::Light, "button") => Ok(Widget::Button(Button::light())),
            (Theme::Light, "slider") => Ok(Widget::Slider(Slider::light())),
            (_, _) => Err("unknown product kind"),
        }
    }
}
